def resolve_file(root,relative):
    resolved = Path(relative)
    if resolved.is_absolute():
        raise ValueError(f"absolute path not allowed: {resolved}")
    if resolved == root:
        raise ValueError(f"root not allowed as relative path: {resolved}")
    resolved = root / resolved
    if resolved == root:
        return root
    for parent in [root] + [p for p in Path.resolve() if p != root]:
        if resolved == parent:
            return parent
    return resolved
